import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:integration_test/integration_test.dart';
import 'package:dio/dio.dart';
import 'package:relay_agent/main.dart' as app;
import 'package:relay_agent/services.dart';
import 'package:relay_agent/kyc_capture.dart';

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets(
    'physical phone screenshot upload, VPS OCR, row review and portal status',
    (tester) async {
      Future<void> wait(Finder finder) async {
        for (var i = 0; i < 300; i++) {
          await tester.pump(const Duration(milliseconds: 250));
          if (finder.evaluate().isNotEmpty) return;
        }
        throw TestFailure('Missing $finder');
      }

      Future<void> reveal(Finder finder) async {
        await tester.scrollUntilVisible(
          finder,
          300,
          scrollable: find.byType(Scrollable).first,
          maxScrolls: 80,
        );
        await tester.pump(const Duration(milliseconds: 300));
      }

      Future<void> tap(String text) async {
        final finder = find.text(text);
        await reveal(finder);
        await tester.tap(finder);
        await tester.pump(const Duration(milliseconds: 500));
      }

      app.main();
      await wait(find.byType(app.Gate));
      final container = ProviderScope.containerOf(
        tester.element(find.byType(app.Gate)),
      );
      final service = container.read(serviceProvider);
      for (var i = 0; i < 150 && !service.ready; i++) {
        await tester.pump(const Duration(milliseconds: 200));
      }
      if (service.user != null) await service.logout();
      await service.login(
        'agent1@relay.demo',
        const String.fromEnvironment('TEST_PASSWORD'),
      );
      await tester.pump(const Duration(seconds: 1));
      final reference = 'DEMO-PHONE-${DateTime.now().millisecondsSinceEpoch}';
      await service.store.put('kyc-draft-${service.user!['id']}', {
        'reference': reference,
        'image':
            '',
        'operation': 'phone-${DateTime.now().microsecondsSinceEpoch}',
        'pending': false,
      });
      app.router.push('/ekyc');
      await wait(find.byType(KycCaptureScreen));
      await wait(find.text('Screenshot saved encrypted on this device.'));
      await binding.convertFlutterSurfaceToImage();
      await tester.pump();
      await binding.takeScreenshot('capture-local-draft');
      await tap('Upload & run VPS OCR');
      await wait(find.text('Status: EXTRACTED'));
      await reveal(find.text('Transaction 1'));
      await tester.enterText(
        find.byType(TextFormField).at(0),
        'DEMO-PHONE-TXN',
      );
      await tester.enterText(find.byType(TextFormField).at(1), 'Jordan Demo');
      await tester.enterText(find.byType(TextFormField).at(2), '0000123');
      await tester.enterText(
        find.byType(TextFormField).at(3),
        'Essential Data 125',
      );
      FocusManager.instance.primaryFocus?.unfocus();
      await tester.pump(const Duration(milliseconds: 300));
      await tap('Save & validate rows');
      await tester.pump(const Duration(seconds: 2));
      await tap('Submit to backend team');
      await tester.pump(const Duration(seconds: 2));
      final all = (await service.dio.get('/kyc-captures')).data as List;
      final row = all.firstWhere((r) => r['source_reference'] == reference);
      final excel = await service.dio.get<List<int>>(
        '/kyc-captures/${row['id']}/excel',
        options: Options(responseType: ResponseType.bytes),
      );
      expect(excel.data!.take(2), [80, 75]);
      final backend = Dio(BaseOptions(baseUrl: apiUrl));
      final auth = await backend.post(
        '/auth/login',
        data: {
          'email': 'compliance@relay.demo',
          'password': const String.fromEnvironment('TEST_PASSWORD'),
          'native': true,
        },
      );
      backend.options.headers['Authorization'] =
          'Bearer ${auth.data['access_token']}';
      await backend.post(
        '/kyc-captures/${row['id']}/review',
        data: {
          'version': row['version'],
          'outcome': 'VERIFIED',
          'reason': 'Checked synthetic phone screenshot',
        },
      );
      await tester.drag(find.byType(Scrollable).first, const Offset(0, 10000));
      await tester.pump();
      await wait(find.text('Status: VERIFIED'));
      expect(tester.takeException(), isNull);
      await tester.ensureVisible(find.text('Status: VERIFIED'));
      await binding.takeScreenshot('capture-phone-verified');
      expect(
        await service.store.get('kyc-draft-${service.user!['id']}'),
        isNull,
      );
      await backend.post('/auth/logout', data: {});
      backend.close();
      app.router.pop();
      await tester.pump();
    },
  );
}
